export const $=id=>document.getElementById(id);
export function formatDate(key){return new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date(`${key}T12:00:00`));}
export function showView(name){for(const view of ['today','archive','settings'])$(view).hidden=view!==name;document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
export function renderEntries(entries,favorites,onOpen){const root=$('entries');root.replaceChildren();if(!entries.length){const p=document.createElement('p');p.className='empty';p.textContent='아직 남겨진 기록이 없어요. 오늘의 마음부터 적어 볼까요?';root.append(p);return;}for(const e of entries){const button=document.createElement('button');button.className='record';const time=document.createElement('time');time.dateTime=e.dateKey;time.textContent=formatDate(e.dateKey)+(favorites.has(e.quoteId)?' · ★':'');const title=document.createElement('strong');title.textContent=e.quoteSnapshot.text;const p=document.createElement('p');p.textContent=e.note.slice(0,110)+(e.strokes.length?' · 그림이 있어요':'');button.append(time,title,p);button.addEventListener('click',()=>onOpen(e.dateKey));root.append(button);}}
export function renderCatalog(quotes,favorites,onToggle){const root=$('catalog');root.replaceChildren();for(const q of quotes){const row=document.createElement('div');row.className='catalog-item';const text=document.createElement('span');text.textContent=q.text;const button=document.createElement('button');button.className='icon-button';button.textContent=favorites.has(q.id)?'★':'☆';button.setAttribute('aria-pressed',String(favorites.has(q.id)));button.setAttribute('aria-label',`${q.text} 즐겨찾기`);button.onclick=()=>onToggle(q.id);row.append(text,button);root.append(row);}}
